import{_ as I,o as i,c as e,a0 as l}from"./chunks/framework.DQOulFGV.js";const a="data:image/svg+xml;base64,",d="data:image/svg+xml;base64,",y=JSON.parse('{"title":"第2章 命令执行与 RESP","description":"","frontmatter":{},"headers":[],"relativePath":"redis/02-standalone-core/chapter-02-command-resp.md","filePath":"redis/02-standalone-core/chapter-02-command-resp.md"}'),g={name:"redis/02-standalone-core/chapter-02-command-resp.md"};function s(n,t,o,m,c,r){return i(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="第2章-命令执行与-resp" tabindex="-1">第2章 命令执行与 RESP <a class="header-anchor" href="#第2章-命令执行与-resp" aria-label="Permalink to &quot;第2章 命令执行与 RESP&quot;">​</a></h1><blockquote><p>一条 <code>SET key value</code> 从客户端发出到 Redis 返回 <code>OK</code>，中间经历了协议编码、网络传输、协议解析、命令查找、执行、响应写回。理解这条链路，才能解释命令是如何被可靠、高效地执行的。</p></blockquote><hr><h2 id="_2-1-resp-协议" tabindex="-1">2.1 RESP 协议 <a class="header-anchor" href="#_2-1-resp-协议" aria-label="Permalink to &quot;2.1 RESP 协议&quot;">​</a></h2><p>RESP（REdis Serialization Protocol）是客户端与 Redis 通信的协议。它简单、易解析、二进制安全。</p><h3 id="五种数据类型" tabindex="-1">五种数据类型 <a class="header-anchor" href="#五种数据类型" aria-label="Permalink to &quot;五种数据类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th style="text-align:left;">首字节</th><th style="text-align:left;">含义</th><th style="text-align:left;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">简单字符串</td><td style="text-align:left;"><code>+</code></td><td style="text-align:left;">简单回复</td><td style="text-align:left;"><code>+OK</code></td></tr><tr><td style="text-align:left;">错误</td><td style="text-align:left;"><code>-</code></td><td style="text-align:left;">错误信息</td><td style="text-align:left;"><code>-ERR unknown command</code></td></tr><tr><td style="text-align:left;">整数</td><td style="text-align:left;"><code>:</code></td><td style="text-align:left;">整数回复</td><td style="text-align:left;"><code>:1000</code></td></tr><tr><td style="text-align:left;">批量字符串</td><td style="text-align:left;"><code>$</code></td><td style="text-align:left;">二进制安全的字符串</td><td style="text-align:left;"><code>$3\\r\\nfoo\\r\\n</code></td></tr><tr><td style="text-align:left;">数组</td><td style="text-align:left;"><code>*</code></td><td style="text-align:left;">多个元素</td><td style="text-align:left;"><code>*2\\r\\n$3\\r\\nfoo\\r\\n$3\\r\\nbar\\r\\n</code></td></tr></tbody></table><h3 id="命令编码格式" tabindex="-1">命令编码格式 <a class="header-anchor" href="#命令编码格式" aria-label="Permalink to &quot;命令编码格式&quot;">​</a></h3><p>客户端把命令编码为「数组 + 批量字符串」的格式发给 Redis：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端发送：SET mykey myvalue</span></span>
<span class="line"><span>实际字节流：*3\\r\\n$3\\r\\nSET\\r\\n$5\\r\\nmykey\\r\\n$7\\r\\nmyvalue\\r\\n</span></span>
<span class="line"><span>             ↑        ↑            ↑</span></span>
<span class="line"><span>             数组3     SET(长度3)    mykey(长度5)  myvalue(长度7)</span></span></code></pre></div><ul><li><code>*3</code>：这是一个包含 3 个元素的数组</li><li><code>$3\\r\\nSET\\r\\n</code>：第一个元素是长度 3 的字符串 &quot;SET&quot;</li><li>依次类推</li></ul><h3 id="内联命令" tabindex="-1">内联命令 <a class="header-anchor" href="#内联命令" aria-label="Permalink to &quot;内联命令&quot;">​</a></h3><p>除了 RESP 格式，Redis 也支持内联命令（空格分隔的纯文本），例如直接发送 <code>PING</code>。这只用于 telnet 等手工调试场景，客户端库一般都用 RESP 格式。</p><hr><h2 id="_2-2-命令解析" tabindex="-1">2.2 命令解析 <a class="header-anchor" href="#_2-2-命令解析" aria-label="Permalink to &quot;2.2 命令解析&quot;">​</a></h2><p>Redis 收到网络字节流后，需要把它解析成内部可执行的命令结构。</p><p>解析流程：</p><p><img src="`+a+`" alt="RESP 命令解析流程"></p><p>解析的关键点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">环节</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">读缓冲区</td><td style="text-align:left;">客户端连接有一个输入缓冲区，读到的字节先暂存于此</td></tr><tr><td style="text-align:left;">协议判断</td><td style="text-align:left;">首字节是 <code>*</code> 走 RESP 多批量命令解析，否则走内联命令解析</td></tr><tr><td style="text-align:left;">参数数组</td><td style="text-align:left;">解析出 <code>argv</code>（参数数组）与 <code>argc</code>（参数个数）</td></tr><tr><td style="text-align:left;">二进制安全</td><td style="text-align:left;">批量字符串按 <code>$长度</code> 精确读取，不依赖 <code>\\0</code> 结尾</td></tr></tbody></table><hr><h2 id="_2-3-命令表查找" tabindex="-1">2.3 命令表查找 <a class="header-anchor" href="#_2-3-命令表查找" aria-label="Permalink to &quot;2.3 命令表查找&quot;">​</a></h2><p>解析出命令名后，Redis 需要找到对应的命令实现。它维护一个命令表——所有命令的哈希表。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>命令表（哈希表，O(1) 查找）</span></span>
<span class="line"><span>  &quot;SET&quot;   → redisCommand { 实现函数, 参数个数, 属性标志 }</span></span>
<span class="line"><span>  &quot;GET&quot;   → redisCommand { ... }</span></span>
<span class="line"><span>  &quot;HSET&quot;  → redisCommand { ... }</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><p><code>redisCommand</code> 结构的关键字段：</p><table tabindex="0"><thead><tr><th style="text-align:left;">字段</th><th style="text-align:left;">作用</th></tr></thead><tbody><tr><td style="text-align:left;">实现函数指针</td><td style="text-align:left;">指向真正执行命令的 C 函数</td></tr><tr><td style="text-align:left;">arity</td><td style="text-align:left;">参数个数，正数=精确，负数=最小参数数</td></tr><tr><td style="text-align:left;">flags</td><td style="text-align:left;">命令属性（写命令/只读命令/管理命令等）</td></tr></tbody></table><p>查找特点：</p><ul><li><strong>O(1) 哈希查找</strong>：命令名作为 key，哈希表直接命中</li><li><strong>大小写不敏感</strong>：命令名统一转小写后查找，<code>SET</code> 与 <code>set</code> 等价</li><li><strong>未知命令报错</strong>：找不到返回 <code>-ERR unknown command</code></li></ul><hr><h2 id="_2-4-执行流程与钩子" tabindex="-1">2.4 执行流程与钩子 <a class="header-anchor" href="#_2-4-执行流程与钩子" aria-label="Permalink to &quot;2.4 执行流程与钩子&quot;">​</a></h2><p>找到命令后，执行过程会经过一系列钩子（Hook），这些钩子承载了 Redis 的很多附加能力。</p><p><img src="`+d+'" alt="命令执行流程"></p><p>执行流程各环节：</p><table tabindex="0"><thead><tr><th style="text-align:left;">环节</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">参数校验</td><td style="text-align:left;">检查参数个数是否符合 arity 要求</td></tr><tr><td style="text-align:left;">键过期检查</td><td style="text-align:left;">惰性删除：访问到已过期 Key 时先删除再执行</td></tr><tr><td style="text-align:left;">执行命令</td><td style="text-align:left;">调用命令对应的实现函数，操作数据结构</td></tr><tr><td style="text-align:left;">慢查询日志</td><td style="text-align:left;">记录执行耗时超过阈值的命令</td></tr><tr><td style="text-align:left;">AOF 传播</td><td style="text-align:left;">写命令追加到 AOF 缓冲区（见第 4 章）</td></tr><tr><td style="text-align:left;">复制传播</td><td style="text-align:left;">写命令同步给从库（见第四卷）</td></tr><tr><td style="text-align:left;">返回响应</td><td style="text-align:left;">把结果编码为 RESP 格式写回客户端</td></tr></tbody></table><blockquote><p>钩子机制的价值：Redis 把「持久化」「复制」等能力通过钩子挂在命令执行链路上，任何写命令都会自动触发 AOF 追加与主从传播，无需命令实现自己操心。这是 Redis 架构简洁的关键设计之一。</p></blockquote>',35)])])}const p=I(g,[["render",s]]);export{y as __pageData,p as default};
